<?php
namespace Database\Seeders;use App\Models\User;use Illuminate\Database\Seeder;use Illuminate\Support\Facades\Hash;use RuntimeException;
class AdminUserSeeder extends Seeder{public function run():void{$email=(string)config('platform.admin.email');$password=(string)config('platform.admin.password');$name=(string)config('platform.admin.name','Administrador EmpleateRD');if($email===''&&$password===''){$this->command?->warn('Administrador omitido: configura ADMIN_EMAIL y ADMIN_PASSWORD.');return;}if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('ADMIN_EMAIL no contiene un correo válido.');if(strlen($password)<12)throw new RuntimeException('ADMIN_PASSWORD debe tener al menos 12 caracteres.');$user=User::firstOrNew(['email'=>$email]);$user->forceFill(['name'=>$name,'account_type'=>'company','password'=>Hash::make($password),'email_verified_at'=>now(),'is_admin'=>true])->save();$this->command?->info("Administrador preparado: {$email}");}}
